import { PLANS } from '@proton/shared/lib/constants';
import type { Organization } from '@proton/shared/lib/interfaces';

import { getInitialStorage } from './MemberStorageSelector';

const organizationForPlan = (PlanName: PLANS) => ({ PlanName }) as Organization;

describe('getInitialStorage', () => {
    it('allocates 500 GB to family organizations', () => {
        expect(getInitialStorage(organizationForPlan(PLANS.FAMILY))).toBe(500 * 1024 ** 3);
    });

    it.each([PLANS.DRIVE_PRO, PLANS.DRIVE_BUSINESS])('allocates 1 TB to %s organizations', (plan) => {
        expect(getInitialStorage(organizationForPlan(plan))).toBe(1024 ** 4);
    });

    it('defaults to 5 GB', () => {
        expect(getInitialStorage()).toBe(5 * 1024 ** 3);
    });
});
